import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Leads real-time board sync (1.8.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leads real-time board sync (1.8.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/leads-realtime-board-sync-1-8-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leads real-time board sync (1.8.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/leads-realtime-board-sync-1-8-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/leads-realtime-board-sync-1-8-0-production-readiness.md","filePath":"deployment/leads-realtime-board-sync-1-8-0-production-readiness.md","lastUpdated":1791219114000}'),s={name:"deployment/leads-realtime-board-sync-1-8-0-production-readiness.md"};function n(r,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="leads-real-time-board-sync-1-8-0-—-production-readiness-audit" tabindex="-1">Leads real-time board sync (1.8.0) — Production Readiness Audit <a class="header-anchor" href="#leads-real-time-board-sync-1-8-0-—-production-readiness-audit" aria-label="Permalink to &quot;Leads real-time board sync (1.8.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-30</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (merge/deploy remaining; live Reverb smoke deferred to staging)</td></tr><tr><td><strong>Scope</strong></td><td>Private board channel <code>tenant.{id}.leads.board</code> + <code>LeadCreated</code>/<code>LeadUpdated</code>/<code>LeadStageChanged</code>/<code>LeadAssigned</code>/<code>LeadDeleted</code> broadcasts; SPA debounce-invalidate hook; catalog <strong>leads 1.7.0 → 1.8.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/leads">Leads developer guide</a> · <a href="/user-guide/leads-overview">Leads overview</a> · <a href="/developer-guide/live-chat">Live Chat developer guide</a> (pattern source) · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>The Leads Kanban board now stays in sync across open tabs/users without a manual refresh. Backend fires five <code>ShouldBroadcastNow</code> events off the existing <code>LeadEventSubscriber</code> domain-event handlers onto a new private Reverb channel; the SPA joins that channel only while the board view is mounted and debounces invalidation of the board + stats queries so a burst of changes (bulk stage move, import) collapses into one refetch. The design deliberately mirrors the <strong>Live Chat inbox invalidate pattern</strong> (refetch-on-signal) and explicitly avoids the <strong>Team Chat message-patching pattern</strong> (no per-card payload merging) to keep the board&#39;s existing filter/sort/pagination logic as the single source of truth for what renders.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel realtime architecture; reuses <code>window.Echo</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Channel auth: same tenant + <code>leads.view</code> (mirrors <code>LiveChatInboxChannel</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Cross-tenant isolation</td><td><strong>Pass</strong> — different <code>tenantId</code> on the channel name is rejected by <code>LeadBoardChannel::join</code></td></tr><tr><td>Broadcasts fire on create / update / stage change / assign / delete</td><td><strong>Pass</strong></td></tr><tr><td><code>previous_stage_id</code> present on stage-changed payload</td><td><strong>Pass</strong></td></tr><tr><td><code>assigned_to</code> present on assigned payload (including unassign → <code>null</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Broadcast failures never break lead writes (<code>safeBroadcast</code> try/catch + <code>report()</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Domain events stay separate from broadcast classes</td><td><strong>Pass</strong> — new <code>App\\Events\\Lead\\*Broadcast</code> namespace; existing <code>App\\Events\\Lead{Created,Updated,...}</code> untouched</td></tr><tr><td>Catalog migrate-only <strong>1.8.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>SPA debounced invalidate (~200ms), board-view-only subscription</td><td><strong>Pass</strong></td></tr><tr><td>Pest coverage</td><td><strong>Pass</strong> — <code>LeadRealtimeBoardTest</code> (7 tests / 17 assertions)</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><code>app/Broadcasting/LeadBoardChannel.php</code> — private channel auth, same shape as <code>LiveChatInboxChannel</code> (tenant match + <code>leads.view</code>).</li><li><code>routes/channels.php</code> — registers <code>tenant.{tenantId}.leads.board</code>.</li><li><code>app/Events/Lead/LeadBoardBroadcastPayload.php</code> — shared payload builder (<code>action</code>, <code>lead_id</code>, <code>uuid</code>, <code>actor_id</code>, <code>stage_id</code>, optional <code>previous_stage_id</code> / <code>assigned_to</code>).</li><li><code>app/Events/Lead/Lead{Created,Updated,StageChanged,Assigned,Deleted}Broadcast.php</code> — <code>ShouldBroadcastNow</code>, each <code>broadcastAs()</code> matching the SPA&#39;s <code>.LeadXxx</code> listener name.</li><li><code>app/Listeners/LeadEventSubscriber.php</code> — each existing domain-event handler now also fires the matching broadcast, wrapped in a <code>safeBroadcast()</code> try/catch/<code>report()</code> guard so a Reverb outage cannot fail a lead create/update/stage-change/assign/delete request.</li><li>Catalog: <code>database/migrations/2026_09_30_120000_bump_leads_module_to_1_8_0.php</code> (migrate-only, reversible) + <code>CatalogSeeder</code> <code>leads</code> version <code>1.7.0 → 1.8.0</code>.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>src/hooks/use-leads-board-realtime.ts</code> — subscribes to the board channel via the existing shared <code>window.Echo</code> instance (never opens/closes the socket itself); listens for all five events; debounces (~200ms) a single invalidate of <code>QUERY_KEYS.leadBoard</code> + <code>QUERY_KEYS.leadStats</code>.</li><li><code>src/pages/leads/leads-page.tsx</code> — calls the hook with <code>enabled: viewMode === &#39;board&#39;</code>, so the table view does not hold an idle channel subscription.</li><li><code>src/types/api.ts</code> — <code>LeadBoardRealtimePayload</code> type for the five events&#39; shared shape.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Leads user/developer guides updated (capability + channel/event reference); product roadmap entry closes the previously deferred &quot;Leads: real-time board sync&quot; item; this readiness doc; CHANGELOG entry.</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Tenant/Lead/LeadRealtimeBoardTest.php</span></span>
<span class="line"><span>Tests: 7 passed (17 assertions)</span></span></code></pre></div><p>Covers: channel auth (owner / <code>leads.view</code> staff / no-permission staff / cross-tenant), <code>LeadCreatedBroadcast</code> on create, <code>LeadUpdatedBroadcast</code> on update, <code>LeadStageChangedBroadcast</code> with correct <code>previous_stage_id</code>, <code>LeadAssignedBroadcast</code> with the new assignee id, <code>LeadDeletedBroadcast</code> on delete, and that a thrown broadcast listener does not prevent the lead write from succeeding.</p><p><code>vendor/bin/pint --dirty --format agent</code> — pass (no style changes needed beyond formatting).</p><p>Frontend <code>npm run typecheck</code> (<code>tsc -b</code>) — pass.</p><h2 id="known-limitations-deferred" tabindex="-1">Known limitations / deferred <a class="header-anchor" href="#known-limitations-deferred" aria-label="Permalink to &quot;Known limitations / deferred&quot;">​</a></h2><ul><li>No Reverb broadcaster runs in CI; broadcast dispatch is verified via <code>Event::fake([...])</code> + <code>Event::assertDispatched(...)</code> (same approach as <code>LiveChatModuleTest</code>) rather than an end-to-end socket round-trip. A live Reverb smoke test on staging is recommended before/at go-live, mirroring how Live Chat was verified.</li><li>No dedicated Playwright realtime spec — two independent browser contexts driving a live Reverb connection is expensive to run in CI and Live Chat itself does not have one either. The Pest dispatch-assertion + manual staging smoke substitutes for now, per the design brief.</li><li>Board cards still fully refetch on any board-relevant event (invalidate, not patch) — intentional, matching the Live Chat inbox pattern; keeps existing filter/sort logic authoritative.</li></ul><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — catalog <code>leads</code> → <strong>1.8.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Open the Leads board in two browser sessions (same tenant, both with <code>leads.view</code>). In session A, create a lead, move a card between stages, assign it, then delete it. Confirm session B&#39;s board + KPI strip update within ~1s without a manual refresh.</li><li>Confirm a user without <code>leads.view</code> cannot subscribe to <code>tenant.{id}.leads.board</code> (channel auth rejects).</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back the catalog migration (<code>down()</code> → <strong>1.7.0</strong>) after rolling back application code. The new broadcast classes and channel are additive — no schema changes, so rollback is code-only plus the catalog version bump.</p>`,25)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
